const updates = [
{time:'08:49',tag:'BREAKING NEWS',title:'Reports of a fire at the World Trade Center',place:'Lower Manhattan, New York',text:'We interrupt our programming for a developing story in New York. Smoke is rising from one of the towers of the World Trade Center. There are early reports of an aircraft striking the building. Details are still emerging. We do not yet have a confirmed account of what happened.',source:'https://transcripts.cnn.com/show/bn/date/2001-09-11/segment/01'},
{time:'09:03',tag:'BREAKING NEWS',title:'A second plane strikes the towers',place:'World Trade Center, New York',text:'A second aircraft has struck the other tower of the World Trade Center. Both buildings are now burning. What began as a report of a single incident has changed dramatically. Emergency crews are responding in lower Manhattan. The full scale of what is happening is not yet clear.'},
{time:'09:30',tag:'PRESIDENTIAL STATEMENT',title:'President calls apparent terrorist attack',place:'Sarasota, Florida',text:'President Bush has addressed the events in New York from Florida, describing an apparent terrorist attack. The president says he will return to Washington. Attention remains on the rescue response at the World Trade Center.'},
{time:'09:40',tag:'DEVELOPING STORY',title:'Reports of an incident at the Pentagon',place:'Arlington, Virginia',text:'We are now following reports of an incident at the Pentagon, outside Washington. Smoke is visible at the building. This is a developing report; the details are not yet clear. Coverage is now focused on both New York and Washington.'},
{time:'09:50',tag:'NATIONAL EMERGENCY',title:'Aircraft ordered to land nationwide',place:'United States',text:'The Federal Aviation Administration has ordered civilian aircraft in United States airspace to land. It is an extraordinary nationwide response. The situation continues to develop as emergency workers respond in New York and at the Pentagon.'},
{time:'09:59',tag:'BREAKING NEWS',title:'South Tower collapses',place:'World Trade Center, New York',text:'The South Tower of the World Trade Center has collapsed. A vast cloud of dust is spreading through lower Manhattan. We cannot yet give a reliable account of how many people were still inside. This is an unfolding catastrophe.'},
{time:'10:28',tag:'BREAKING NEWS',title:'North Tower collapses',place:'World Trade Center, New York',text:'The remaining tower has now collapsed. Both towers of the World Trade Center are gone. Dust and debris have engulfed the surrounding streets. The immediate focus is on those trying to escape and the emergency workers attempting to reach them.'},
{time:'11:00',tag:'DEVELOPING STORY',title:'Plane crash reported in Pennsylvania',place:'Somerset County, Pennsylvania',text:'A passenger plane crash is now being reported in western Pennsylvania, near Shanksville. This is another developing part of the story. The circumstances and the experiences of those aboard are not yet known to the public.'},
{time:'12:00',tag:'CONTINUING COVERAGE',title:'Rescue efforts continue',place:'New York • Washington • Pennsylvania',text:'It is noon in the East. Rescue operations continue at the World Trade Center and the Pentagon, while authorities respond to the crash in Pennsylvania. Families are seeking news of loved ones. The number of people lost remains uncertain.'},
{time:'13:04',tag:'PRESIDENTIAL STATEMENT',title:'President addresses the nation again',place:'Barksdale Air Force Base, Louisiana',text:'President Bush has delivered another statement, this time from Louisiana. He says the government is responding and that those responsible will be pursued. Rescue work continues, and the nation is still trying to understand the scale of the attacks.'},
{time:'17:20',tag:'BREAKING NEWS',title:'7 World Trade Center collapses',place:'Lower Manhattan, New York',text:'A further building in the World Trade Center complex, Seven World Trade Center, has collapsed after burning for hours. The building had been evacuated. The rescue effort in lower Manhattan continues into the evening.'},
{time:'20:30',tag:'ADDRESS TO THE NATION',title:'A nation hears from its president',place:'The White House, Washington',text:'President Bush has addressed the nation from the White House. He has spoken of the lives taken, the emergency response, and the search for those responsible. In New York and Washington, rescue crews continue their work. For countless families, the wait for news goes on.'}
];
const $=id=>document.getElementById(id);let current=0,playing=false,muted=false,timer=null,speech=null,generation=0,startedAt=0;const synth=window.speechSynthesis;const seen=new Set([0]);
$('skyline').src='skyline.jpg';
function clock(t){let [h,m]=t.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h<12?'AM':'PM'}`}
function render(){const u=updates[current];$('headline').textContent=u.title;$('strap').textContent=u.tag;$('subline').textContent=u.place;$('tvTime').textContent=clock(u.time)+' ET';$('clock').innerHTML=u.time+':00 <small>ET</small>';$('chapterTitle').textContent=u.title;$('script').textContent=u.text;$('ticker').textContent=u.title.toUpperCase()+'   •   RECONSTRUCTED COVERAGE · SEPTEMBER 11, 2001';$('play').textContent=playing?'Ⅱ':'▶';$('play').setAttribute('aria-label',playing?'Pause broadcast':'Play broadcast');$('centerPlay').hidden=playing;$('chapters').innerHTML=[...seen].sort((a,b)=>b-a).map(i=>`<button class="chapter ${i===current?'selected':''}" data-index="${i}" aria-current="${i===current}"><time>${clock(updates[i].time)}</time><span><strong>${updates[i].title}</strong><small>${updates[i].tag}</small></span></button>`).join('');document.querySelector('.now .eyebrow').innerHTML='ON THE AIR <i>UPDATE '+String(current+1).padStart(2,'0')+'</i>';$('next').textContent=current===updates.length-1?'Replay from first report ↺':'Next report →';$('broadcast').classList.toggle('on-air',playing);}
function cancel(){generation++;clearTimeout(timer);if(synth)synth.cancel();speech=null}
function schedule(token){if(!playing||token!==generation)return;if(current===updates.length-1){playing=false;render();$('voiceStatus').textContent='COVERAGE CONTINUES BEYOND THIS RECONSTRUCTION';return}const u=updates[current],next=updates[current+1];const toMin=t=>Number(t.slice(0,2))*60+Number(t.slice(3));const wait=$('speed').value==='1'?Math.max(2000,(toMin(next.time)-toMin(u.time))*60000-(Date.now()-startedAt)):2400;timer=setTimeout(()=>go(current+1),wait)}
function speak(){cancel();if(!playing)return;const token=generation;startedAt=Date.now();if(!synth||muted){$('voiceStatus').textContent=muted?'NARRATION MUTED':'VOICE UNAVAILABLE · READ TRANSCRIPT';timer=setTimeout(()=>schedule(token),Math.max(12000,updates[current].text.split(' ').length*390));return}speech=new SpeechSynthesisUtterance(updates[current].text);speech.lang='en-US';speech.rate=.94;const voices=synth.getVoices();speech.voice=voices.find(v=>v.lang==='en-US'&&/Samantha|Aaron|Daniel/.test(v.name))||voices.find(v=>v.lang==='en-US')||null;speech.onend=()=>{if(token===generation){$('voiceStatus').textContent='AWAITING NEXT REPORT';schedule(token)}};speech.onerror=e=>{if(token!==generation)return;$('voiceStatus').textContent='VOICE UNAVAILABLE · READ TRANSCRIPT';timer=setTimeout(()=>schedule(token),20000)};$('voiceStatus').textContent='SYNTHETIC ANCHOR NARRATION';synth.speak(speech)}
function go(i){current=Math.max(0,Math.min(updates.length-1,i));seen.add(current);render();speak()}
function toggle(){playing=!playing;render();if(playing)speak();else{cancel();$('voiceStatus').textContent='PAUSED'}}
$('play').onclick=toggle;$('centerPlay').onclick=toggle;$('next').onclick=()=>{if(current===updates.length-1){seen.clear();seen.add(0);go(0)}else go(current+1)};$('chapters').onclick=e=>{const b=e.target.closest('[data-index]');if(b)go(Number(b.dataset.index))};$('sound').onclick=()=>{muted=!muted;$('sound').textContent=muted?'◖×':'◖))';$('sound').setAttribute('aria-label',muted?'Unmute narration':'Mute narration');speak()};$('speed').onchange=()=>speak();$('captions').onclick=()=>{const hidden=!$('transcript').hidden;$('transcript').hidden=hidden;$('captions').setAttribute('aria-pressed',String(!hidden))};$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.querySelector('.tv').requestFullscreen()}catch{$('voiceStatus').textContent='FULLSCREEN UNAVAILABLE IN THIS BROWSER'}};for(const id of ['sourcesOpen','sourcesFooter'])$(id).onclick=()=>$('sources').showModal();$('sourcesClose').onclick=()=>$('sources').close();$('sources').onclick=e=>{if(e.target===$('sources'))$('sources').close()};window.addEventListener('pagehide',cancel);render();
